import {
	Bot,
	Check,
	CircleCheck,
	ListTodo,
	MessageCircle,
	Network,
	Paperclip,
	Search,
	ShieldQuestion,
} from 'lucide-react';
import {useEffect, useMemo, useRef, useState} from 'react';

import {fetchSkills, type SkillInfo} from '@/lib/api';
import {cn} from '@/lib/utils';
import type {AgentMode} from '@/lib/agentMode';

/**
 * Composer 左侧 + 按钮的 Cursor 风格三段式快捷菜单。
 *
 * 布局：顶部搜索框 → 模式区（Plan / Ask / Agent）→ 技能区（来自 /v1/skills）→
 * 操作区（Multi-Agent 开关 / 添加文件）。所有视觉沿用 XEYO 令牌（玻璃底
 * xy-menu-flyout + --xy-* 语义色 + mono 键位 + ease-out-soft 过渡）。
 */

type Mode = {
	mode: AgentMode;
	label: string;
	description: string;
	Icon: typeof ListTodo;
};

const MODES: Mode[] = [
	{
		mode: 'plan',
		label: 'Plan',
		description: '先生成一份实现计划，确认后再动手',
		Icon: ListTodo,
	},
	{
		mode: 'ask',
		label: 'Ask',
		description: '只回答问题，不修改任何文件',
		Icon: MessageCircle,
	},
	{
		mode: 'agent',
		label: 'Agent',
		description: '默认：直接执行并产出结果',
		Icon: Bot,
	},
];

const SOURCE_LABEL: Record<string, string> = {
	workspace: '工作区',
	home: '用户',
	plugin: '插件',
};

type Props = {
	open: boolean;
	/** 当前会话工作区根（空串=未绑定） */
	workspace: string;
	agentMode: AgentMode;
	multiAgent: boolean;
	uploading: boolean;
	onSelectMode: (mode: AgentMode) => void;
	onToggleMultiAgent: () => void;
	onAddFile: () => void;
	onPickSkill: (skill: SkillInfo) => void;
};

export function ComposerQuickMenu({
	open,
	workspace,
	agentMode,
	multiAgent,
	uploading,
	onSelectMode,
	onToggleMultiAgent,
	onAddFile,
	onPickSkill,
}: Props) {
	const [query, setQuery] = useState('');
	const [skills, setSkills] = useState<SkillInfo[] | null>(null);
	const [skillsError, setSkillsError] = useState(false);
	const [loadedWorkspace, setLoadedWorkspace] = useState('');
	const searchRef = useRef<HTMLInputElement>(null);

	// 每次打开的重置搜索并聚焦。
	useEffect(() => {
		if (open) {
			setQuery('');
			requestAnimationFrame(() => searchRef.current?.focus());
		}
	}, [open]);

	// 打开且工作区变化时拉取技能（幂等：同工作区不重复拉）。
	useEffect(() => {
		if (!open) {
			return;
		}
		if (loadedWorkspace === workspace && skills !== null) {
			return;
		}
		let cancelled = false;
		setSkillsError(false);
		void fetchSkills(workspace).then(report => {
			if (cancelled) {
				return;
			}
			if (!report || report.ok === false) {
				setSkillsError(true);
				setSkills(report?.enabled_extensions === false ? [] : null);
			} else {
				setSkills(report.skills);
			}
			setLoadedWorkspace(workspace);
		});
		return () => {
			cancelled = true;
		};
	}, [open, workspace, skills, loadedWorkspace]);

	const q = query.trim().toLowerCase();

	const filteredModes = useMemo(
		() =>
			!q
				? MODES
				: MODES.filter(
						m =>
							m.label.toLowerCase().includes(q) ||
							m.description.toLowerCase().includes(q),
					),
		[q],
	);

	const filteredSkills = useMemo(() => {
		const list = skills ?? [];
		if (!q) {
			return list;
		}
		return list.filter(
			s =>
				s.name.toLowerCase().includes(q) ||
				s.description.toLowerCase().includes(q) ||
				s.source.toLowerCase().includes(q),
		);
	}, [skills, q]);

	const hasMode = filteredModes.length > 0;
	const hasSkill = filteredSkills.length > 0;
	const noMatch = Boolean(q) && !hasMode && !hasSkill;
	const empty = !q && hasMode;

	return (
		<div
			role="menu"
			className="xy-menu-flyout absolute bottom-full left-0 z-50 mb-1.5 flex max-h-[min(420px,60vh)] w-[300px] flex-col overflow-hidden rounded-2xl border border-line/50 p-1.5"
		>
			{/* 搜索框 */}
			<label className="flex h-8 shrink-0 items-center gap-2 rounded-lg bg-ink/[0.06] px-2.5">
				<Search className="h-3.5 w-3.5 shrink-0 text-mute" strokeWidth={1.9} />
				<input
					ref={searchRef}
					value={query}
					onChange={e => setQuery(e.target.value)}
					placeholder="搜索模式、技能、操作…"
					className="min-w-0 flex-1 bg-transparent text-[12.5px] text-ink outline-none placeholder:text-mute"
				/>
			</label>

			<div className="xy-menu-scroll mt-1 min-h-0 flex-1 overflow-y-auto">
				{/* 模式区 */}
				<div className="px-2 pb-0.5 pt-2 text-[10px] font-medium uppercase tracking-[0.08em] text-mute">
					模式
				</div>
				<div className="flex flex-col gap-0.5">
					{filteredModes.map(m => {
						const Icon = m.Icon;
						const active = agentMode === m.mode;
						return (
							<button
								key={m.mode}
								type="button"
								role="menuitemradio"
								aria-checked={active}
								onClick={() => onSelectMode(m.mode)}
								className={cn(
									'xy-menu-row flex w-full items-start gap-2 px-2 py-1.5 text-left',
									active && 'is-active',
								)}
							>
								<Icon
									className="mt-0.5 h-4 w-4 shrink-0 text-accent"
									strokeWidth={1.9}
								/>
								<span className="min-w-0 flex-1">
									<span className="block text-[13px] font-medium text-ink">
										{m.label}
									</span>
									<span className="block truncate text-[11px] leading-snug text-mute">
										{m.description}
									</span>
								</span>
								<span className="flex items-start pt-0.5">
									{active ? (
										<Check
											className="h-3.5 w-3.5 shrink-0 text-accent"
											strokeWidth={2.4}
										/>
									) : (
										<kbd className="rounded border border-line/70 bg-glass-strong px-1 py-px font-mono text-[9px] text-mute">
											Alt+↘
										</kbd>
									)}
								</span>
							</button>
						);
					})}
				</div>

				{/* 技能区 */}
				<div className="px-2 pb-0.5 pt-2.5 text-[10px] font-medium uppercase tracking-[0.08em] text-mute">
					技能
				</div>
				{empty ? (
					<p className="px-2 pb-1 pt-1 text-[11.5px] leading-snug text-mute">
						扩展层未启用，或当前工作区没有技能。可运行 /skills 查看。
					</p>
				) : skillsError && (skills ?? []).length === 0 ? (
					<p className="px-2 pb-1 pt-1 text-[11.5px] leading-snug text-mute">
						技能加载失败。
					</p>
				) : filteredSkills.map(s => {
					const source = SOURCE_LABEL[s.source] ?? s.source;
					return (
						<button
							key={`${s.source}:${s.name}`}
							type="button"
							role="menuitem"
							onClick={() => onPickSkill(s)}
							className="xy-menu-row flex w-full items-start gap-2 px-2 py-1.5 text-left"
						>
							<CircleCheck
								className="mt-0.5 h-4 w-4 shrink-0 text-mute"
								strokeWidth={1.75}
							/>
							<span className="min-w-0 flex-1">
								<span className="flex items-center gap-1.5">
									<span className="block truncate font-mono text-[12.5px] font-medium text-ink">
										{s.name}
									</span>
									<span className="shrink-0 rounded bg-ink/[0.06] px-1 py-px font-mono text-[9px] text-mute">
										{source}
									</span>
								</span>
								{s.description ? (
									<span className="block truncate text-[11px] leading-snug text-mute">
										{s.description}
									</span>
								) : null}
							</span>
						</button>
					);
				})}

				{noMatch && (
					<p className="px-2 py-2 text-[11.5px] text-mute">无匹配项。</p>
				)}
			</div>

			{/* 操作区 */}
			<div role="separator" className="my-1 h-px bg-line/60" />
			<div className="flex flex-col gap-0.5">
				<button
					type="button"
					role="menuitemcheckbox"
					aria-checked={multiAgent}
					title={
						multiAgent
							? '已开启：软提示偏向使用 Agent（不强制）'
							: '开启后软提示偏向 Agent；关闭时主模型仍可主动调用'
					}
					onClick={onToggleMultiAgent}
					className={cn(
						'xy-menu-row flex w-full items-center gap-2 px-2 py-1.5 text-left text-[13px]',
						multiAgent ? 'text-accent' : 'text-ink-soft',
					)}
				>
					<Network className="h-4 w-4 shrink-0 text-accent" strokeWidth={1.9} />
					<span className="flex-1">Multi-Agent</span>
					{multiAgent ? (
						<Check className="h-3.5 w-3.5 shrink-0 text-accent" strokeWidth={2.4} />
					) : null}
				</button>
				<button
					type="button"
					role="menuitem"
					disabled={uploading}
					onClick={onAddFile}
					className="xy-menu-row flex w-full items-center gap-2 px-2 py-1.5 text-left text-[13px] text-ink-soft disabled:cursor-default disabled:text-mute/55"
				>
					<Paperclip className="h-4 w-4 shrink-0 text-accent" strokeWidth={1.9} />
					<span>添加文件</span>
				</button>
			</div>
		</div>
	);
}

