import {cleanup, render, screen, waitFor} from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import {afterEach, describe, expect, it, vi} from 'vitest';
import {ComposerQuickMenu} from './ComposerQuickMenu';
import type {SkillInfo} from '@/lib/api';

vi.mock('@/lib/api', () => ({
	fetchSkills: vi.fn(),
}));

// eslint-disable-next-line @typescript-eslint/no-explicit-any
const fetchSkillsMock = vi.mocked((await import('@/lib/api')).fetchSkills as any);

afterEach(() => {
	cleanup();
	vi.clearAllMocks();
});

const SKILLS: SkillInfo[] = [
	{
		name: 'archify',
		description: 'Create polished architecture diagrams',
		source: 'workspace',
		plugin: '',
		tags: [],
		model_hint: '',
	},
	{
		name: 'greeter',
		description: '演示欢迎语',
		source: 'plugin',
		plugin: 'demo',
		tags: [],
		model_hint: '',
	},
];

function renderQuick(opts: {
	open?: boolean;
	workspace?: string;
	agentMode?: 'agent' | 'plan' | 'ask';
	multiAgent?: boolean;
	uploading?: boolean;
	onSelectMode?: (m: 'agent' | 'plan' | 'ask') => void;
	onToggleMultiAgent?: () => void;
	onAddFile?: () => void;
	onPickSkill?: (s: SkillInfo) => void;
} = {}) {
	const props = {
		open: opts.open ?? true,
		workspace: opts.workspace ?? 'D:\\proj',
		agentMode: opts.agentMode ?? 'agent',
		multiAgent: opts.multiAgent ?? false,
		uploading: opts.uploading ?? false,
		onSelectMode: opts.onSelectMode ?? vi.fn(),
		onToggleMultiAgent: opts.onToggleMultiAgent ?? vi.fn(),
		onAddFile: opts.onAddFile ?? vi.fn(),
		onPickSkill: opts.onPickSkill ?? vi.fn(),
	};
	const utils = render(<ComposerQuickMenu {...props} />);
	return {...utils, props};
}

describe('ComposerQuickMenu', () => {
	it('renders search box, modes, actions and skill rows', async () => {
		fetchSkillsMock.mockResolvedValue({
			ok: true,
			enabled_extensions: true,
			skills: SKILLS,
		});
		renderQuick();
		expect(
			screen.getByPlaceholderText('搜索模式、技能、操作…'),
		).toBeTruthy();
		expect(screen.getByText('模式')).toBeTruthy();
		expect(screen.getByText('技能')).toBeTruthy();
		expect(screen.getByText('Plan')).toBeTruthy();
		expect(screen.getByText('Ask')).toBeTruthy();
		expect(screen.getByText('Agent')).toBeTruthy();
		expect(screen.getByText('Multi-Agent')).toBeTruthy();
		expect(screen.getByText('添加文件')).toBeTruthy();
		await waitFor(() => {
			expect(screen.getByText('archify')).toBeTruthy();
			expect(screen.getByText('greeter')).toBeTruthy();
		});
	});

	it('marks the active mode with a check and selects on click', async () => {
		fetchSkillsMock.mockResolvedValue({
			ok: true,
			enabled_extensions: false,
			skills: [],
		});
		const onSelectMode = vi.fn();
		renderQuick({agentMode: 'plan', onSelectMode});
		const planRow = screen.getByRole('menuitemradio', {name: /Plan/});
		expect(planRow.getAttribute('aria-checked')).toBe('true');
		await userEvent.click(screen.getByRole('menuitemradio', {name: /Ask/}));
		expect(onSelectMode).toHaveBeenCalledWith('ask');
	});

	it('filters modes and skills by the search query', async () => {
		fetchSkillsMock.mockResolvedValue({
			ok: true,
			enabled_extensions: true,
			skills: SKILLS,
		});
		renderQuick();
		await waitFor(() => {
			expect(screen.getByText('archify')).toBeTruthy();
		});
		await userEvent.type(
			screen.getByPlaceholderText('搜索模式、技能、操作…'),
			'arch',
		);
		expect(screen.getByText('archify')).toBeTruthy();
		expect(screen.queryByText('greeter')).toBeNull();
		expect(screen.queryByText('Plan')).toBeNull();
	});

	it('shows an empty hint when extensions are disabled', async () => {
		fetchSkillsMock.mockResolvedValue({
			ok: true,
			enabled_extensions: false,
			skills: [],
		});
		renderQuick();
		await waitFor(() => {
			expect(screen.getByText(/扩展层未启用/)).toBeTruthy();
		});
	});

	it('shows a failure hint when the fetch errors', async () => {
