				className="xy-menu-row flex w-full items-center gap-2 rounded-lg px-2.5 py-1.5 text-left"
			>
				<CircleCheck
					className="h-4 w-4 shrink-0 text-mute"
					strokeWidth={1.75}
				/>
				<span className="min-w-0 flex-1 truncate">
					<span className="font-mono text-[12.5px] font-medium text-ink">
						{s.name}
					</span>
					<span className="ml-2 text-[11px] text-mute">
						{s.description}
					</span>
				</span>
			</button>
		))}
		{slashSuggest.length > 0 && slashSkills.length > 0 ? (
			<div role="separator" className="my-1 h-px bg-line/60" />
		) : null}
		{slashSuggest.length > 0 ? (
			<div className="px-1 pb-0.5 pt-1 text-[10px] font-medium uppercase tracking-[0.08em] text-mute">
				命令
			</div>
		) : null}
		{slashSuggest.map(c => (
			<button
				key={c.name}
				type="button"
				role="option"
				aria-selected={false}
				onMouseDown={e => e.preventDefault()}
				onClick={() => {
					setValue(`${c.usage} `);
					taRef.current?.focus();
				}}
				className="xy-menu-row flex w-full flex-col items-start gap-0.5 rounded-lg px-2.5 py-1.5 text-left"
			>
				<span className="font-mono text-[12.5px] text-accent">
					{c.usage}
				</span>
				<span className="text-[11.5px] text-mute">
					{c.summary}
				</span>
			</button>
		))}
	</div>
)}

